/**
 * FloatingChatButton.jsx
 * Floating button that toggles chat interface
 * Fully integrated with splash_screen.html chat functionality
 */

import React, { useState } from 'react';
import './FloatingChatButton.css';

const FloatingChatButton = ({ isOpen, onClick, hasPendingMessages = false }) => {
  const [isHovered, setIsHovered] = useState(false);

  return (
    <button
      className={`floating-chat-button ${isOpen ? 'active' : ''}`}
      onClick={onClick}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      title={isOpen ? 'Close Chat' : 'Open Chat'}
      style={{
        position: 'fixed',
        bottom: '20px',
        right: '20px',
        width: '60px',
        height: '60px',
        borderRadius: '50%',
        background: isHovered
          ? 'linear-gradient(135deg, rgba(0, 255, 136, 0.9), rgba(0, 200, 136, 1))'
          : 'linear-gradient(135deg, rgba(0, 255, 136, 0.7), rgba(0, 200, 136, 0.8))',
        border: '2px solid rgba(0, 255, 136, 0.5)',
        cursor: 'pointer',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        fontSize: '24px',
        boxShadow: hasPendingMessages 
          ? '0 4px 12px rgba(0, 255, 136, 0.5), 0 0 20px rgba(0, 255, 136, 0.4)' 
          : '0 4px 12px rgba(0, 255, 136, 0.3), inset 0 1px 0 rgba(255, 255, 255, 0.2)',
        transition: 'all 0.3s ease',
        zIndex: 1000,
      }}
    >
      <div
        className="chat-button-icon"
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          width: '100%',
          height: '100%',
          zIndex: 1001
        }}
      >
        {isOpen ? '✕' : '💬'}
      </div>

      {!isOpen && (
        <>
          <style>{`
            @keyframes chatButtonFloat {
              0%, 100% { transform: translateY(0px); }
              50% { transform: translateY(-10px); }
            }
            @keyframes chatButtonPulse {
              0% {
                transform: scale(1);
                opacity: 1;
              }
              100% {
                transform: scale(1.3);
                opacity: 0;
              }
            }
            .chat-button-pulse {
              animation: chatButtonPulse 1.5s ease-out infinite;
            }
          `}</style>
          <div
            className="chat-button-pulse"
            style={{
              position: 'absolute',
              width: '100%',
              height: '100%',
              borderRadius: '50%',
              border: '2px solid rgba(0, 255, 136, 0.5)',
            }}
          />
        </>
      )}

      {hasPendingMessages && (
        <div
          style={{
            position: 'absolute',
            top: '-8px',
            right: '-8px',
            width: '24px',
            height: '24px',
            borderRadius: '50%',
            background: 'linear-gradient(135deg, #ff4444, #ff0000)',
            color: 'white',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            fontSize: '12px',
            fontWeight: 'bold',
            boxShadow: '0 2px 8px rgba(255, 0, 0, 0.4)'
          }}
        >
          !
        </div>
      )}
    </button>
  );
};

export default FloatingChatButton;
